function splitStatements(sql) {
  const withoutComments = sql.split("\n").filter((line) => !line.trim().startsWith("--")).join("\n");
  return withoutComments.split(";").map((s) => s.trim()).filter((s) => s.length > 0);
}
async function applyPendingMigrations(prisma2) {
  const applied = [];
  const alreadyApplied = [];
  for (const migration of MIGRATIONS) {
    const existing = await prisma2.$queryRaw`
      SELECT finished_at FROM _prisma_migrations WHERE migration_name = ${migration.name} LIMIT 1
    `;
    if (existing.length > 0 && existing[0].finished_at !== null) {
      alreadyApplied.push(migration.name);
      continue;
    }
    const statements = splitStatements(migration.sql);
    for (const statement of statements) {
      await prisma2.$executeRawUnsafe(statement);
    }
    const checksum = createHash2("sha256").update(migration.sql).digest("hex");
    await prisma2.$executeRaw`
      INSERT INTO _prisma_migrations (id, checksum, migration_name, started_at, finished_at, applied_steps_count)
      VALUES (gen_random_uuid()::text, ${checksum}, ${migration.name}, now(), now(), ${statements.length})
    `;
    applied.push(migration.name);
  }
  return { applied, alreadyApplied };
}

